    def _extrair_tomador_nfcom_net_mund(self, t: str) -> Entidade:
        """Extrai o destinatário (tomador) de uma NFCom da NET MUND BRASIL.

        Bloco com rótulos "CLIENTE:"/"CNPJ:"/"ENDEREÇO:" em ordem DIRETA,
        mesmo formato do NFCOM_LOTEC_FIBRA/RLGR/SETE_CONNECT (`CNPJ?` tolera
        o "CNP:" sem o "J" já visto no SETE_CONNECT, mesmo que não ocorra
        nesta nota específica).

        A quebra de linha 1 do endereço usa `\\s+-\\s+` (hífen com espaço
        OBRIGATÓRIO dos 2 lados) em vez do `\\s*-\\s*` (espaço opcional) dos
        irmãos - achado real, nota nº 683: "RODOVIA BA-535 - VIA PARAFUSO,
        535 - BOULEVARD-GIRAFFAS - PONTO CERTO" tem um hífen SEM espaços
        dentro do nome composto do complemento ("BOULEVARD-GIRAFFAS", nome
        do empreendimento) - com espaço opcional, o regex compartilhado dos
        irmãos quebra o complemento ao meio nesse hífen interno
        ("BOULEVARD"/"GIRAFFAS - PONTO CERTO"), produzindo bairro errado.
        Exigindo espaço nos 2 lados do separador real, o hífen interno do
        nome composto (sem espaço ao redor) é ignorado e só o hífen
        separador de verdade (" - ", com espaço) quebra os campos."""
        cnpj_tom, nome_tom = "00000000000000", "Tomador Não Identificado"
        logradouro, numero, complemento, bairro = "Não informado", "S/N", "", "Não informado"
        municipio, uf, cep = "Não informado", "BA", "00000000"

        m_bloco = re.search(
            r'CLIENTE\s*:\s*\n+(.+?)\n+CNPJ?\s*:\s*(\d{2}[.\s]?\d{3}[.\s,]?\d{3}[/.,]?\d{4}-?\d{2})',
            t, re.IGNORECASE)
        if m_bloco:
            nome_tom = m_bloco.group(1).strip() or nome_tom
            candidato = re.sub(r'\D', '', m_bloco.group(2))
            if self._validate_cnpj_cpf(candidato):
                cnpj_tom = candidato

        m_end = re.search(r'ENDERE[ÇC]O\s*:\s*\n+(.+?)\n+(.+?)(?:\n|$)', t, re.IGNORECASE)
        if m_end:
            linha1 = m_end.group(1).strip()
            m1 = re.match(r'^(.*?),\s*(\S+)\s+-\s+(.*?)\s+-\s+(.*)$', linha1)
            if m1:
                logradouro = m1.group(1).strip() or logradouro
                numero = m1.group(2).strip() or numero
                complemento = m1.group(3).strip()
                bairro = m1.group(4).strip() or bairro

            linha2 = m_end.group(2).strip()
            m2 = re.match(r'^(.*?)\s*/\s*([A-Z]{2})\s*-\s*(\d+)$', linha2, re.IGNORECASE)
            if m2:
                municipio = m2.group(1).strip()
                uf = m2.group(2).strip().upper()
                cep = m2.group(3).strip()

        mun_cod = _ibge_resolver.extract_and_validate(municipio, uf, city_hint=municipio)

        return Entidade(
            cnpj_cpf=cnpj_tom,
            razao_social=nome_tom,
            endereco=Endereco(
                logradouro=logradouro,
                numero=numero,
                complemento=complemento,
                bairro=bairro,
                codigo_municipio=mun_cod,
                municipio=municipio,
                uf=uf,
                cep=cep,
            ),
        )

